exercise.solution:
class TaskController {
    private tasks: { id: number; title: string; done: boolean }[] = [];
    private nextId = 1;

    list(query?: { done?: boolean }) {
        const tasks = query?.done === undefined
            ? [...this.tasks]
            : this.tasks.filter(task => task.done === query.done);

        return { status: 200, body: tasks };
    }

    get(id: number) {
        const task = this.tasks.find(task => task.id === id);

        if (!task) {
            return { status: 404, body: { error: "Task not found" } };
        }

        return { status: 200, body: task };
    }

    create(dto: { title: string }) {
        const task = {
            id: this.nextId++,
            title: dto.title,
            done: false
        };

        this.tasks.push(task);

        return {
            status: 201,
            headers: { Location: `/api/tasks/${task.id}` },
            body: task
        };
    }

    update(id: number, dto: { title?: string; done?: boolean }) {
        const task = this.tasks.find(task => task.id === id);

        if (!task) {
            return { status: 404, body: { error: "Task not found" } };
        }

        if (dto.title !== undefined) {
            task.title = dto.title;
        }

        if (dto.done !== undefined) {
            task.done = dto.done;
        }

        return { status: 200, body: task };
    }

    remove(id: number) {
        const index = this.tasks.findIndex(task => task.id === id);

        if (index === -1) {
            return { status: 404, body: { error: "Task not found" } };
        }

        this.tasks.splice(index, 1);
        return { status: 204, body: null };
    }
}

